double mlp_loss_and_grad(const double* params, int n_in, int n_hidden,
                         const double* X, const double* y, int n_samples,
                         double* grad) {
    const double* W1 = params;
    const double* b1 = params + n_hidden * n_in;
    const double* W2 = b1 + n_hidden;
    double b2 = W2[n_hidden];

    int w1_size = n_hidden * n_in;
    int b1_off = w1_size;
    int w2_off = b1_off + n_hidden;
    int b2_off = w2_off + n_hidden;
    int total = b2_off + 1;

    for (int i = 0; i < total; ++i) {
        grad[i] = 0.0;
    }

    double total_loss = 0.0;

    for (int s = 0; s < n_samples; ++s) {
        const double* x = X + s * n_in;
        double yv = y[s];

        double z = b2;
        for (int j = 0; j < n_hidden; ++j) {
            double a = b1[j];
            const double* w1j = W1 + j * n_in;
            for (int k = 0; k < n_in; ++k) {
                a += w1j[k] * x[k];
            }
            double h = std::tanh(a);
            z += W2[j] * h;
        }

        double p, logp, log1mp;
        if (z >= 0.0) {
            double e = std::exp(-z);
            p = 1.0 / (1.0 + e);
            logp = -std::log(1.0 + e);
            log1mp = -z - std::log(1.0 + e);
        } else {
            double e = std::exp(z);
            p = e / (1.0 + e);
            logp = z - std::log(1.0 + e);
            log1mp = -std::log(1.0 + e);
        }

        double loss;
        if (yv == 1.0) {
            loss = -logp;
        } else {
            loss = -log1mp;
        }
        total_loss += loss;

        double dz = p - yv;

        grad[b2_off] += dz;

        for (int j = 0; j < n_hidden; ++j) {
            double a = b1[j];
            const double* w1j = W1 + j * n_in;
            for (int k = 0; k < n_in; ++k) {
                a += w1j[k] * x[k];
            }
            double h = std::tanh(a);
            double da = dz * W2[j] * (1.0 - h * h);

            grad[w2_off + j] += dz * h;
            grad[b1_off + j] += da;

            double* gw1j = grad + j * n_in;
            for (int k = 0; k < n_in; ++k) {
                gw1j[k] += da * x[k];
            }
        }
    }

    double inv_n = 1.0 / static_cast<double>(n_samples);
    for (int i = 0; i < total; ++i) {
        grad[i] *= inv_n;
    }

    return total_loss * inv_n;
}

